SELECT r.condition, r.id, r.run_kind, r.status, r.usage_cost, r.protocol_key, r.protocol_status, r.protocol_turn_id, r.protocol_run_id, r.protocol_parent_run_id, r.protocol_prior_run_id, r.protocol_client_message_id, r.protocol_resumed_by_run_id, r.protocol_source_key, r.protocol_initial_turn_key, r.protocol_input_hash, r.protocol_input_json, r.protocol_pending_json, r.protocol_revision, r.protocol_last_sequence, r.protocol_lease_owner, r.protocol_lease_until, r.protocol_lease_revision, r.turn_id, r.schedule_id, r.conversation_id, r.conversation_kind, r.attempt, r.resumed_from_run_id, r.error_code, r.error_message, r.iteration, r.max_iterations, r.checkpoint_response_id, r.checkpoint_message_id, r.checkpoint_data, r.agent_id, r.model_provider, r.model, r.worker_id, r.worker_pid, r.worker_host, r.lease_owner, r.lease_until, r.last_heartbeat_at, r.security_context, r.effective_user_id, r.auth_authority, r.auth_audience, r.user_cred_url, r.heartbeat_interval_sec, r.scheduled_for, r.precondition_ran_at, r.precondition_passed, r.precondition_result, r.usage_prompt_tokens, r.usage_completion_tokens, r.usage_total_tokens, r.created_at, r.updated_at, r.started_at, r.completed_at FROM (SELECT t.* FROM  (SELECT c.* , NULL AS `condition`, 0 AS should_delete FROM run c WHERE COALESCE(c.run_kind,'execution')='execution'
)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)